  domestic: {
    light: { standard: 5, express: 25 },
    heavy: { standard: 20, express: 50 }
  },
  international: {
    light: { standard: 15, express: 60 },
    heavy: { standard: 40, express: 100 }
  }
}.freeze

def shipping_cost(order)
  region = order[:country] == "US" ? :domestic : :international
  weight_class = order[:weight] > 10 ? :heavy : :light
  speed = order[:express] ? :express : :standard

  SHIPPING_RATES[region][weight_class][speed]
end
